===== EnsureUniqueTelephone =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;

/**
 * Rejects a create request whose normalized telephone is already used by any existing owner. Runs
 * after {@link NormalizeTelephone}, so the request telephone is already the canonical E.164 form;
 * each stored telephone is normalized the same way before comparison. A collision is a 409 via
 * {@link DuplicateTelephoneException}.
 */
public class EnsureUniqueTelephone {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateTelephoneException {
        String telephone = request.getTelephone();
        for (Owner owner : ownerRepository.findAll()) {
            if (telephone.equals(TelephoneNormalizer.toE164(owner.getTelephone()))) {
                throw new DuplicateTelephoneException(telephone);
            }
        }
    }
}
===== EnsureUniqueEmail =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateEmailException;

/**
 * Rejects a create request whose email is already used by any existing owner. Runs after
 * {@link NormalizeEmail}, so the request email is already the canonical lower-cased form; each stored
 * email is lower-cased the same way before comparison. An absent or blank email is unconstrained. A
 * collision is a 409 via {@link DuplicateEmailException}.
 */
public class EnsureUniqueEmail {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateEmailException {
        String email = request.getEmail();
        if (email == null || email.isBlank()) {
            return;
        }
        for (Owner owner : ownerRepository.findAll()) {
            String existing = owner.getEmail();
            if (existing != null && email.equals(EmailNormalizer.normalize(existing))) {
                throw new DuplicateEmailException(email);
            }
        }
    }
}
===== EnsureUniqueHousehold =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;

/**
 * Rejects a create request that would place the new owner in a household already occupied by an
 * existing owner — same last name and address, compared case-insensitively with whitespace collapsed
 * (see {@link HouseholdNormalizer}). A collision is a 409 via {@link DuplicateHouseholdException},
 * unless the request sets {@code sharesHousehold} true to acknowledge the shared household.
 */
public class EnsureUniqueHousehold {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateHouseholdException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String key = HouseholdNormalizer.key(request.getLastName(), request.getAddress());
        for (Owner owner : ownerRepository.findAll()) {
            if (key.equals(HouseholdNormalizer.key(owner.getLastName(), owner.getAddress()))) {
                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
            }
        }
    }
}
