package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;

/**
 * Normalizes the telephone of a create request to canonical E.164 form (see
 * {@link TelephoneNormalizer#toE164(String)}). The normalized value is written back onto the
 * (republished) request so {@link BuildOwner} stores and later responses return the E.164 form. A
 * value that cannot form a valid E.164 number is rejected as a 400 via
 * {@link InvalidTelephoneException}.
 */
public class NormalizeTelephone {

    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
        String e164 = TelephoneNormalizer.toE164(request.getTelephone());
        if (e164 == null) {
            throw new InvalidTelephoneException(request.getTelephone());
        }
        request.setTelephone(e164);
    }
}
===== NormalizeEmail =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;

/**
 * Normalizes the optional email of a create request: an absent or blank email is left untouched, while
 * a present one must be a syntactically valid address. The lower-cased form is written back onto the
 * (republished) request so {@link BuildOwner} stores and later responses return it lower-cased. An
 * invalid value is rejected as a 400 via {@link InvalidEmailException}.
 */
public class NormalizeEmail {

    public void service(@Val OwnerFieldsDto request) throws InvalidEmailException {
        String email = request.getEmail();
        if (email == null || email.isBlank()) {
            return;
        }
        String normalized = EmailNormalizer.normalize(email);
        if (!EmailNormalizer.isValid(normalized)) {
            throw new InvalidEmailException(email);
        }
        request.setEmail(normalized);
    }
}
===== AssignHousehold =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * When the create request sets {@code sharesHousehold} true and the new owner joins a household
 * already occupied by an existing owner (same last name and address, see {@link HouseholdNormalizer}),
 * stamps the new owner and every existing member of that household with the same stable
 * {@link HouseholdNormalizer#id(String, String) household id}. Without {@code sharesHousehold} the
 * request never reaches here as a joiner — {@link EnsureUniqueHousehold} rejects the collision first —
 * so a lone owner keeps a null household id. Runs after {@link BuildOwner} and mutates the built
 * {@link Owner} in place; existing members are re-saved so a later read returns the shared id too.
 */
public class AssignHousehold {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String key = HouseholdNormalizer.key(owner.getLastName(), owner.getAddress());
        boolean joinsHousehold = false;
        String householdId = HouseholdNormalizer.id(owner.getLastName(), owner.getAddress());
        for (Owner member : ownerRepository.findAll()) {
            if (!key.equals(HouseholdNormalizer.key(member.getLastName(), member.getAddress()))) {
                continue;
            }
            joinsHousehold = true;
            if (!householdId.equals(member.getHouseholdId())) {
                member.setHouseholdId(householdId);
                ownerRepository.save(member);
            }
        }
        if (joinsHousehold) {
            owner.setHouseholdId(householdId);
        }
    }
}
===== BuildOwner =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

public class BuildOwner {

    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built) {
        built.set(ownerMapper.toOwner(request));
    }
}
