package org.springframework.samples.petclinic.rest.function.owner;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * Canonical telephone normalization shared by the create pipeline: {@link NormalizeTelephone} stores
 * the E.164 form, {@link EnsureUniqueTelephone} compares by it and {@link ValidateTelephoneLength}
 * checks its national-number length. Not a pipeline step, so it is free to expose plain helpers.
 */
public final class TelephoneNormalizer {

    /** Minimum digits after the '+' for a valid E.164 number. */
    private static final int MIN_E164_DIGITS = 8;

    /** Maximum digits after the '+' for a valid E.164 number. */
    private static final int MAX_E164_DIGITS = 15;

    /** Default country code assumed when no leading '+' is present. */
    private static final String DEFAULT_COUNTRY_CODE = "61";

    /**
     * Required national-number digit count per E.164 country code. Ordered longest code first so
     * {@link #hasValidNationalLength(String)} matches the most specific prefix (e.g. '61' before '1').
     */
    private static final Map<String, Integer> NATIONAL_LENGTH_BY_COUNTRY = new LinkedHashMap<>();

    static {
        NATIONAL_LENGTH_BY_COUNTRY.put("61", 9); // Australia
        NATIONAL_LENGTH_BY_COUNTRY.put("1", 10); // NANP (e.g. US)
    }

    private TelephoneNormalizer() {
    }

    /**
     * Converts a raw telephone to canonical E.164 form, or returns {@code null} when it cannot form a
     * valid E.164 number. A leading '+' and country code are kept when present; otherwise the default
     * country code '+61' is assumed and a single leading '0' is dropped from the national digits.
     * Spaces, dashes and brackets (any non-digit) are stripped. The result must have 8 to 15 digits
     * after the '+'.
     */
    public static String toE164(String telephone) {
        if (telephone == null) {
            return null;
        }
        boolean hasCountryCode = telephone.trim().startsWith("+");
        String digits = telephone.replaceAll("\\D", "");
        if (!hasCountryCode) {
            if (digits.startsWith("0")) {
                digits = digits.substring(1);
            }
            digits = DEFAULT_COUNTRY_CODE + digits;
        }
        if (digits.length() < MIN_E164_DIGITS || digits.length() > MAX_E164_DIGITS) {
            return null;
        }
        return "+" + digits;
    }

    /**
     * Whether an E.164 number's national-number length matches what its country code requires (e.g.
     * '+61' expects 9 national digits, '+1' expects 10). Numbers whose country code has no configured
     * rule are accepted, so this only rejects a wrong length for a known country. Expects the canonical
     * form produced by {@link #toE164(String)}.
     */
    public static boolean hasValidNationalLength(String e164) {
        if (e164 == null || !e164.startsWith("+")) {
            return false;
        }
        String digits = e164.substring(1);
        for (Map.Entry<String, Integer> rule : NATIONAL_LENGTH_BY_COUNTRY.entrySet()) {
            String countryCode = rule.getKey();
            if (digits.startsWith(countryCode)) {
                return digits.length() - countryCode.length() == rule.getValue();
            }
        }
        return true;
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.util.regex.Pattern;

/**
 * Canonical email handling shared by the create pipeline: {@link NormalizeEmail} lower-cases the
 * stored form and validates syntax through it. Not a pipeline step, so it is free to expose plain
 * helpers.
 */
public final class EmailNormalizer {

    /** A syntactically valid address: a local part, an {@code @}, then a dotted domain. */
    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");

    private EmailNormalizer() {
    }

    /** Whether {@code email} is a syntactically valid address. */
    public static boolean isValid(String email) {
        return email != null && EMAIL.matcher(email).matches();
    }

    /** The stored form: trimmed and lower-cased. */
    public static String normalize(String email) {
        return email.trim().toLowerCase();
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

/**
 * Canonical household comparison shared by the create pipeline: {@link EnsureUniqueHousehold} uses it
 * to decide whether two owners share a household and {@link AssignHousehold} uses it to derive the
 * shared household id. A household is identified by last name plus address: the last name is compared
 * case-insensitively with runs of whitespace collapsed to a single space and outer whitespace trimmed,
 * and the address is compared in its canonical form (see {@link AddressNormalizer}). Not a pipeline
 * step, so it is free to expose plain helpers.
 */
public final class HouseholdNormalizer {

    private HouseholdNormalizer() {
    }

    /**
     * The stable household identifier derived from an owner's last name and address. Owners with
     * equal {@link #key(String, String) keys} share the same id, and the id never changes for a given
     * household, so it can be recomputed for late joiners rather than stored and looked up.
     */
    public static String id(String lastName, String address) {
        return "H-" + sha256hex(key(lastName, address)).substring(0, 12).toUpperCase();
    }

    private static String sha256hex(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder hex = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                hex.append(String.format("%02x", b));
            }
            return hex.toString();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 not available", e);
        }
    }

    /**
     * Builds the canonical household key for an owner from its last name and address. Two owners
     * belong to the same household when their keys are equal. Either field may be {@code null}, which
     * normalizes to an empty token.
     */
    public static String key(String lastName, String address) {
        // '\n' separates the fields so that a boundary shift (e.g. "ab"+"c" vs "a"+"bc") cannot forge a
        // collision; it never appears in a normalized value.
        return normalizeName(lastName) + "\n" + AddressNormalizer.normalize(address);
    }

    /** Lower-cases and collapses whitespace to single spaces, trimming the ends; {@code null} → "". */
    private static String normalizeName(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}

